 root=E.fromstring(parts['word/document.xml']);body=root.find('w:body',NS);ps=body.findall('w:p',NS);find=lambda s:next(p for p in ps if txt(p).startswith(s));template=find('We compared both graph pruning strategies with the prefix-clustering');heading=find('Controlled speed comparison with clustering and multiple alignment');caption_template=find('Table 5 Reconstruction time');foot_template=find('Time is mean ± sample s.d.')
